import React, {useState, useCallback, useRef} from 'react'
import {createPortal} from 'react-dom'
import {Button, IconButton, Flash, ButtonGroup, ActionMenu, ActionList} from '@primer/react'

import {AgentIcon, TriangleDownIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {TOGGLE_COPILOT_OVERLAY} from '@github-ui/global-agents-menu/GlobalAgentsMenu'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useCreateFixWorkflowJob} from './hooks/use-create-fix-workflow-job'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import styles from './FixWorkflowButton.module.css'

const FIX_WORKFLOW_BUTTON_ID = 'fix-workflow-button'

interface FixWorkflowButtonProps {
  displayName?: string
  jobUrl?: string
  checkRunId?: number
  /** @deprecated Use checkRunId instead. Kept for backward compatibility during deploy. */
  runId?: number
  defaultBranch?: string
  createAgentSessionPath: string
}

export function FixWorkflowButton({
  displayName,
  jobUrl,
  checkRunId: checkRunIdProp,
  runId,
  defaultBranch,
  createAgentSessionPath,
}: FixWorkflowButtonProps) {
  // Support both new (checkRunId) and legacy (runId) prop names
  const checkRunId = checkRunIdProp ?? runId
  const [isLoading, setIsLoading] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const [isMenuOpen, setIsMenuOpen] = useState(false)
  const buttonGroupRef = useRef<HTMLDivElement>(null)

  const details = `Analyze the Actions logs, identify the root cause of the failure, and implement a fix.
Check run ID: ${checkRunId || ''}
Job URL: ${jobUrl || ''}`

  const quotedDisplayName = displayName ? ` "${displayName}"` : ''
  const eventContent = `Fix the failing GitHub Actions job${quotedDisplayName}`
  const problemStatement = `${eventContent}\n${details}`
  const customPromptStatement = `Create a PR to fix the failing GitHub Actions job${quotedDisplayName}\n${details}`

  const {mutate: createFixJob} = useCreateFixWorkflowJob({
    createAgentSessionPath,
    onSuccess: data => {
      sendEvent('fix_workflow.job_created', {
        source: FIX_WORKFLOW_BUTTON_ID,
      })
      // Redirect to the copilot agents page
      if (data.redirectUrl) {
        window.location.href = data.redirectUrl
      } else {
        window.location.href = '/copilot/agents'
      }
    },
    onError: error => {
      setIsLoading(false)
      setErrorMessage('Failed to create Copilot cloud agent job')
      sendEvent('fix_workflow.job_creation_failed', {
        error: error.message,
        source: FIX_WORKFLOW_BUTTON_ID,
      })
    },
  })

  const handleFixWorkflow = useCallback(() => {
    setIsLoading(true)
    setErrorMessage(null) // Clear any previous errors
    sendEvent('fix_workflow.button_clicked', {
      source: FIX_WORKFLOW_BUTTON_ID,
      check_run_id: checkRunId,
    })

    createFixJob({
      problemStatement,
      baseRef: defaultBranch || '',
      eventType: 'fix_failed_workflow',
      eventUrl: jobUrl || '',
      eventContent,
      checkRunId,
    })
  }, [createFixJob, defaultBranch, jobUrl, problemStatement, checkRunId, eventContent])

  const handleOpenAgentsPanel = useCallback(() => {
    sendEvent('fix_workflow.open_agents_panel_clicked', {
      source: FIX_WORKFLOW_BUTTON_ID,
      check_run_id: checkRunId,
    })

    // Set the task entrypoint message and branch so the agents panel opens with the prompt prefilled
    copilotLocalStorage.setTaskEntrypointMessage(customPromptStatement, undefined, defaultBranch)

    // Open the agents panel
    document.dispatchEvent(new CustomEvent(TOGGLE_COPILOT_OVERLAY))
    setIsMenuOpen(false)
  }, [customPromptStatement, checkRunId, defaultBranch])

  // Return early if we don't have the required path
  if (!createAgentSessionPath) return null

  return (
    <div className={styles.container}>
      {/* Compact variant (icon only for mobile) */}
      <IconButton
        className={clsx(styles.fixWorkflowButton, styles.compact)}
        icon={AgentIcon}
        aria-label="Fix with Copilot"
        style={{boxShadow: 'none'}}
        onClick={handleFixWorkflow}
        loading={isLoading}
      />

      {/* Expanded variant (split button for desktop) */}
      <ButtonGroup ref={buttonGroupRef} className={clsx(styles.fixWorkflowButton, styles.expanded)}>
        <Button
          onClick={handleFixWorkflow}
          loading={isLoading}
          style={{boxShadow: 'none'}}
          variant="primary"
          leadingVisual={AgentIcon}
        >
          Fix with Copilot
        </Button>
        <IconButton
          aria-label="More fix options"
          aria-expanded={isMenuOpen}
          icon={TriangleDownIcon}
          variant="primary"
          onClick={() => setIsMenuOpen(prev => !prev)}
          style={{boxShadow: 'none'}}
        />
      </ButtonGroup>

      <ActionMenu anchorRef={buttonGroupRef} open={isMenuOpen} onOpenChange={setIsMenuOpen}>
        <ActionMenu.Overlay>
          <ActionList>
            <ActionList.Item onSelect={handleOpenAgentsPanel}>Customize prompt</ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>

      {/* Error message - render in global flash container if available */}
      {errorMessage && <FlashError message={errorMessage} />}
    </div>
  )
}

function FlashError({message}: {message: string}) {
  const [container, setContainer] = useState<HTMLElement | null>(null)

  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setContainer(document.getElementById('js-flash-container'))
  }, [])

  const flashElement = (
    <Flash full variant="danger">
      {message}
    </Flash>
  )

  // If the global flash container exists, portal into it for consistent UX with Rails flash messages
  if (container) {
    return createPortal(flashElement, container)
  }

  // Fallback to inline display if container isn't available
  return (
    <Flash variant="danger" className={styles.errorFlash}>
      {message}
    </Flash>
  )
}
